export const CAD_ROWS_SQL = `SELECT DISTINCT ON (prop_id)
  prop_id::text AS prop_id,
  tax_year,
  situs_address, situs_city, situs_zip, legal_description, exemption_codes,
  land_value, improvement_value, market_value, assessed_value, year_built,
  living_area_sqft, land_acres, property_use_code
  FROM cad_property
 WHERE county_fips = $1
   AND prop_id::text = ANY($2)
 ORDER BY prop_id, tax_year DESC`;

export const LANDING_ROWS_SQL = `SELECT prop_id, disposition, method, place_fips, city_name
  FROM landing_parcel_jurisdiction
 WHERE county_fips = $1
   AND prop_id = ANY($2)`;

export async function loadLandingAndCad(cortex, county, propIds) {
  const landing = await cortex.query(LANDING_ROWS_SQL, [county, propIds]);
  const cad = await cortex.query(CAD_ROWS_SQL, [county, propIds]);
  const landingByProp = new Map(landing.rows.map((r) => [String(r.prop_id), r]));
  const cadByProp = new Map(cad.rows.map((r) => [String(r.prop_id), r]));
  const crosswalk = await loadWilliamsonCrosswalk(cortex, county, [...cadByProp.keys()]);
  for (const [propId, crosswalkRow] of crosswalk) {
    cadByProp.set(propId, mergeWilliamsonCrosswalk(cadByProp.get(propId), crosswalkRow));
  }
  return { landingByProp, cadByProp };
}
